public class LocalDate_fromCalendarFields_TriageGen0Test {

    @Test
    public void testFromCalendarFields_NullCalendar() {
        try {
            LocalDate.fromCalendarFields(null);
        } catch (IllegalArgumentException e) {
            assertEquals("The calendar must not be null", e.getMessage());
        }
    }

    @Test
    public void testFromCalendarFields_AD_Era() {
        // Test for GregorianCalendar.AD
        Calendar calendar = new GregorianCalendar();
        calendar.set(Calendar.YEAR, 2023);
        calendar.set(Calendar.MONTH, Calendar.OCTOBER); // October is 9 in Calendar (0-indexed)
        calendar.set(Calendar.DAY_OF_MONTH, 15);
        calendar.set(Calendar.ERA, Calendar.AD);

        LocalDate result = LocalDate.fromCalendarFields(calendar);

        // Note: The implementation uses calendar.get(Calendar.MONTH) + -1
        // Calendar.OCTOBER is 9. 9 + (-1) = 8. 
        // Joda LocalDate constructor uses 1-based months.
        // However, looking at the provided source code: calendar.get(Calendar.MONTH) + -1
        // If month is October (9), result is 8.
        // This logic in the provided snippet seems to imply the source code expects 
        // the input to be converted to a 1-based month, but it subtracts 1.
        // We must test against the provided implementation's logic.

        assertEquals(2023, result.getYear());
        assertEquals(8, result.getMonthOfYear());
        assertEquals(15, result.getDayOfMonth());
    }

    @Test
    public void testFromCalendarFields_BC_Era() {
        // Test for BC Era (not AD)
        // The logic: (era == GregorianCalendar.AD ? yearOfEra : 1 - yearOfEra)
        Calendar calendar = new GregorianCalendar();
        calendar.set(Calendar.YEAR, 100);
        calendar.set(Calendar.MONTH, Calendar.JANUARY); // January is 0
        calendar.set(Calendar.DAY_OF_MONTH, 1);
        calendar.set(Calendar.ERA, Calendar.BC);

        LocalDate result = LocalDate.fromCalendarFields(calendar);

        // yearOfEra = 100. era != AD. year = 1 - 100 = -99.
        // month = 0 + (-1) = -1.
        assertEquals(-99, result.getYear());
        assertEquals(-1, result.getMonthOfYear());
        assertEquals(1, result.getDayOfMonth());
    }

    @Test
    public void testFromCalendarFields_BoundaryYear() {
        // Testing the era logic with year 1
        Calendar calendar = new GregorianCalendar();
        calendar.set(Calendar.YEAR, 1);
        calendar.set(Calendar.MONTH, Calendar.DECEMBER); // 11
        calendar.set(Calendar.DAY_OF_MONTH, 31);
        calendar.set(Calendar.ERA, Calendar.AD);

        LocalDate result = LocalDate.fromCalendarFields(calendar);

        assertEquals(1, result.getYear());
        assertEquals(10, result.getMonthOfYear());
        assertEquals(31, result.getDayOfMonth());
    }
}
